export const confirmImageImportBodyHoldingsItemPriceDateRegExp = new RegExp('^\\d{4}-\\d{2}-\\d{2}$');
export const confirmImageImportBodyHoldingsMax = 100;

export const confirmImageImportBodyEntriesItemDescriptionMax = 160;

export const confirmImageImportBodyEntriesItemCategoryMax = 50;

export const confirmImageImportBodyEntriesItemAmountCentsMax = 100000000000;

export const confirmImageImportBodyEntriesItemDateRegExp = new RegExp('^\\d{4}-\\d{2}-\\d{2}$');
export const confirmImageImportBodyEntriesItemNotesMax = 2000;

export const confirmImageImportBodyEntriesMax = 1;



export const ConfirmImageImportBody = zod.object({
  "requestId": zod.string().uuid(),
  "kind": zod.enum(['holdings', 'receipt']),
  "allowDuplicates": zod.boolean(),
  "holdings": zod.array(zod.object({
  "symbol": zod.string().min(1).max(confirmImageImportBodyHoldingsItemSymbolMax).regex(confirmImageImportBodyHoldingsItemSymbolRegExp),
  "name": zod.string().min(1).max(confirmImageImportBodyHoldingsItemNameMax),
  "type": zod.enum(['ETF', 'Stock', 'Bond', 'Cash', 'Crypto', 'Other']),
  "quantity": zod.number().gt(confirmImageImportBodyHoldingsItemQuantityExclusiveMin).max(confirmImageImportBodyHoldingsItemQuantityMax),
  "priceCents": zod.number().int().min(confirmImageImportBodyHoldingsItemPriceCentsMin).max(confirmImageImportBodyHoldingsItemPriceCentsMax),
  "costBasisCents": zod.number().int().min(confirmImageImportBodyHoldingsItemCostBasisCentsMin).max(confirmImageImportBodyHoldingsItemCostBasisCentsMax).nullable(),
  "notes": zod.string().max(confirmImageImportBodyHoldingsItemNotesMax),
  "priceDate": zod.string().regex(confirmImageImportBodyHoldingsItemPriceDateRegExp)
})).max(confirmImageImportBodyHoldingsMax),
  "entries": zod.array(zod.object({
  "description": zod.string().min(1).max(confirmImageImportBodyEntriesItemDescriptionMax),
  "category": zod.string().min(1).max(confirmImageImportBodyEntriesItemCategoryMax),
  "type": zod.enum(['Income', 'Expense']),
  "amountCents": zod.number().int().min(1).max(confirmImageImportBodyEntriesItemAmountCentsMax),
  "date": zod.string().regex(confirmImageImportBodyEntriesItemDateRegExp),
  "notes": zod.string().max(confirmImageImportBodyEntriesItemNotesMax)
})).max(confirmImageImportBodyEntriesMax)
})

export const confirmImageImportResponseHoldingCountMin = 0;

export const confirmImageImportResponseEntryCountMin = 0;

export const confirmImageImportResponseSkippedCountMin = 0;



export const ConfirmImageImportResponse = zod.object({
  "holdingCount": zod.number().int().min(confirmImageImportResponseHoldingCountMin),
  "entryCount": zod.number().int().min(confirmImageImportResponseEntryCountMin),
  "skippedCount": zod.number().int().min(confirmImageImportResponseSkippedCountMin),
  "alreadySaved": zod.boolean()
})


